carrier_event = {
	id = action.42
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		owner = {
			OR = {
				has_policy_flag = appropriation_allowed
				has_ethic = ethic_gestalt_consciousness
			}
		}
		OR = {
			pop_amount > 1000
			AND = {
				pop_amount > 300
				free_housing < 100
			}
		}
	}

	immediate = {
		set_variable = {
			which = land_appropriated
			value = 0
		}
		random_list = {
			25 = {
				while = {
					count = 5
					if = {
						limit = {
							OR = {
								pop_amount > 1000
								AND = {
									pop_amount > 300
									free_housing < 100
								}
							}
						}
						random_owned_pop_group = {
							limit = {
								is_sapient = yes
								has_citizenship_rights = no
								NOT = {
									has_citizenship_type = {
										type = citizenship_assimilation
										country = owner
									}
								}
							}
							displace_pop_amount = {
								amount = 100
								random = 10
							}
							root = {
								change_variable = {
									which = land_appropriated
									value = 1
								}
							}
						}
					}
				}
			}
			25 = {
				while = {
					count = 4
					if = {
						limit = {
							OR = {
								pop_amount > 1000
								AND = {
									pop_amount > 300
									free_housing < 100
								}
							}
						}
						random_owned_pop_group = {
							limit = {
								is_sapient = yes
								has_citizenship_rights = no
								NOT = {
