										type = citizenship_assimilation
										country = owner
									}
								}
							}
							displace_pop_amount = {
								amount = 100
								random = 10
							}
							root = {
								change_variable = {
									which = land_appropriated
									value = 1
								}
							}
						}
					}
				}
			}
			25 = {
				while = {
					count = 3
					if = {
						limit = {
							OR = {
								pop_amount > 1000
								AND = {
									pop_amount > 300
									free_housing < 100
								}
							}
						}
						random_owned_pop_group = {
							limit = {
								is_sapient = yes
								has_citizenship_rights = no
								NOT = {
									has_citizenship_type = {
										type = citizenship_assimilation
										country = owner
									}
								}
							}
							displace_pop_amount = {
								amount = 100
								random = 10
							}
							root = {
								change_variable = {
									which = land_appropriated
									value = 1
								}
							}
						}
					}
				}
			}
		}

		while = {
			count = land_appropriated

			owner = {
				if = {
					limit = {
						any_owned_planet = {
							free_housing < 100
							any_owned_pop_group = {
								is_sapient = yes
								has_citizenship_rights = yes
								OR = {
									is_pop_category = worker
									is_pop_category = simple_drone
								}
								can_live_on_planet = root
							}
						}
					}

					random_owned_planet = {
						limit = {
							free_housing < 100
							any_owned_pop_group = {
								is_sapient = yes
								has_citizenship_rights = yes
								OR = {
									is_pop_category = worker
									is_pop_category = simple_drone
								}
								can_live_on_planet = root
							}
						}

						random_owned_pop_group = {
							limit = {
								is_sapient = yes
								has_citizenship_rights = yes
								OR = {
									is_pop_category = worker
									is_pop_category = simple_drone
								}
								can_live_on_planet = root
							}

							resettle_pop_group = {
								POP_GROUP = this
								PLANET = root
								AMOUNT = 100
							}
						}
					}
				}
				else_if = {
					limit = {
						any_owned_planet = {
							any_owned_pop_group = {
								is_sapient = yes
								has_citizenship_rights = yes
								OR = {
									is_pop_category = worker
									is_pop_category = simple_drone
								}
								can_live_on_planet = root
							}
						}
					}

					random_owned_planet = {
						limit = {
							any_owned_pop_group = {
								is_sapient = yes
								has_citizenship_rights = yes
								OR = {
									is_pop_category = worker
									is_pop_category = simple_drone
								}
								can_live_on_planet = root
							}
						}

						random_owned_pop_group = {
							limit = {
								is_sapient = yes
								has_citizenship_rights = yes
								OR = {
									is_pop_category = worker
									is_pop_category = simple_drone
								}
								can_live_on_planet = root
							}

							resettle_pop_group = {
								POP_GROUP = this
								PLANET = root
								AMOUNT = 100
							}
						}
					}
				}
			}
		}
		clear_variable = land_appropriated

		if = {
			limit = {
				owner = { NOT = { has_ethic = ethic_gestalt_consciousness } }
			}
			add_modifier = {
				modifier = "land_appropriation"
				years = 5
			}
		}
	}
