script:
event = {
	id = action.90
	hide_window = yes
	is_triggered_only = yes
	trigger = {
		any_country = {
			is_nomadic = no
			OR = {
				is_country_type = default
				is_fallen_empire = yes
			}
			any_owned_planet = {
				is_controlled_by = PREV
				solar_system = {
					NOT = {
						exists = starbase
					}
				}
			}
		}
	}
	immediate = {
		every_system = {
			limit = {
				NOT = { exists = starbase }
				any_system_planet_colony = {
					carrier_is_type = planet
					exists = owner
					has_ground_combat = no
					OR = {
						has_shroud_dlc = no
						AND = {
							has_shroud_dlc = yes
							NOT = {
								has_carrier_flag = exile_planet
							}
						}
					}
					owner = {
						OR = {
							AND = {
								is_country_type = default
								is_nomadic = no
							}
							is_country_type = fallen_empire
							is_country_type = awakened_fallen_empire
						}
					}
					solar_system = {
						NOR = {
							any_fleet_in_system = {
								exists = owner
								owner = {
									NOT = { is_same_value = prevprevprev.owner }
									OR = {
										is_hostile = prevprevprev.owner
										is_at_war_with = prevprevprev.owner
									}
								}
								is_cloaked = no
							}
							any_fleet_in_system = {
								exists = controller
								controller = {
									NOT = { is_same_value = prevprevprev.owner }
									OR = {
										is_hostile = prevprevprev.owner
										is_at_war_with = prevprevprev.owner
									}
								}
								is_cloaked = no
							}
							any_system_planet_colony = {
								exists = owner
								NOT = { is_same_value = prevprev }
								owner = {
									NOT = { is_same_value = prevprevprev.owner }
									OR = {
										is_country_type = default
										is_country_type = fallen_empire
										is_country_type = awakened_fallen_empire
									}
								}
							}
						}
					}
				}
			}
			random_system_planet = {
				limit = {
					is_colony = yes
					exists = owner
					has_ground_combat = no
					OR = {
						has_shroud_dlc = no
						AND = {
							has_shroud_dlc = yes
							NOT = {
								has_carrier_flag = exile_planet
							}
						}
					}
					owner = {
						OR = {
							is_country_type = default
							is_country_type = fallen_empire
							is_country_type = awakened_fallen_empire
						}
					}
					solar_system = {
						NOR = {
							any_fleet_in_system = {
								exists = owner
								owner = {
									NOT = { is_same_value = prevprevprev.owner }
									OR = {
										is_hostile = prevprevprev.owner
										is_at_war_with = prevprevprev.owner
									}
								}
								is_cloaked = no
							}
							any_fleet_in_system = {
								exists = controller
								controller = {
									NOT = { is_same_value = prevprevprev.owner }
									OR = {
										is_hostile = prevprevprev.owner
										is_at_war_with = prevprevprev.owner
									}
								}
								is_cloaked = no
							}
							any_system_planet_colony = {
								exists = owner
								owner = {
									NOT = { is_same_value = prevprevprev.owner }
									OR = {
										is_country_type = default
										is_country_type = fallen_empire
										is_country_type = awakened_fallen_empire
									}
								}
							}
						}
					}
				}
				# Fruitful Origin - the outpost is being created for the first time
				if = {
					limit = {
						has_carrier_flag = seed_pods_colonization
					}
					carrier_event = { id = origin.7400 }
				}
				# else, fire the normal "Outpost Rebuilt!" event
				else = {
					carrier_event = { id = action.91 }
				}
			}
		}
	}
}

