	id = action.92
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		any_country = { is_country_type = swarm }
	}

	immediate = {
		random_country = {
			limit = {
				is_country_type = swarm
			}
			save_event_target_as = prethoryn_swarm
		}
