					}
				}
				destroy_colony = yes
				change_pc = pc_ringworld_habitable_damaged
				reset_planet = yes
			}
			else_if = {
				limit = {
					is_under_colonization = yes
					NOR = {
						is_planet_class = pc_habitat
						is_planet_class = pc_ringworld_habitable
					}
				}
				change_pc = pc_infested
				set_owner = event_target:prethoryn_swarm
			}
		}
	}
}

