colony_event = {
	id = action.361
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		exists = owner
		owner = {
			check_modifier_value = {
				modifier = colony_start_urban_districts_add
				value > 0
			}
		}
	}

	immediate = {
		set_timed_carrier_flag = {
			flag = ignore_ai_building_limitations
			days = 1
		}
		if = {
			limit = {
				planet_is_ring_world_equivalent = yes
			}
			while = {
				count = owner.modifier:colony_start_urban_districts_add
				add_district = {
					district_type = district_rw_city
					type_conversion = yes
				}
			}
		}
		else_if = {
			limit = {
				planet_is_habitat_equivalent = yes
			}
			while = {
				count = owner.modifier:colony_start_urban_districts_add
				add_district = {
					district_type = district_hab_housing
					type_conversion = yes
				}
			}
		}
		else = {
			while = {
				count = owner.modifier:colony_start_urban_districts_add
				add_district = {
					district_type = district_city
					type_conversion = yes
				}
			}
			validate_planet_buildings_and_districts = yes
			if = {
				limit = {
					owner = {
						is_regular_empire = yes
					}
					NOT = {
						has_building = building_colony_shelter
					}
				}
				add_building = building_colony_shelter
			}
			else_if = {
				limit = {
					owner = {
						is_machine_empire = yes
					}
					NOT = {
						has_building = building_deployment_post
					}
				}
				add_building = building_deployment_post
			}
			else_if = {
				limit = {
					owner = {
						is_hive_empire = yes
						is_wilderness_empire = no
					}
					NOT = {
						has_building = building_hive_capital
					}
				}
				add_building = building_hive_capital
			}
			else_if = {
				limit = {
					owner = {
						is_wilderness_empire = yes
					}
					NOR = {
						has_building = building_colony_shelter_wilderness
						has_building = building_capital_wilderness
						has_building = building_major_capital_wilderness
						has_building = building_system_capital_wilderness
						has_building = building_imperial_capital_wilderness
					}
				}
				add_building = building_colony_shelter_wilderness
			}
		}
	}
}

